with t(s,n) as (values
 ('costing','costing_refresh_run'),('costing','costing_refresh_run_stage'),('costing','cost_pool_monthly_snapshot'),('costing','direct_labour_component_pool_snapshot'),
 ('costing','sku_sales_allocation_basis_snapshot'),('costing','product_production_overhead_workload_snapshot'),('costing','product_production_overhead_step_snapshot'),
 ('costing','sku_production_overhead_allocation_snapshot'),('costing','product_direct_labour_workload_snapshot'),('costing','product_direct_labour_step_snapshot'),
 ('costing','sku_packing_labour_workload_snapshot'),('costing','sku_direct_labour_allocation_snapshot'),('costing','batch_true_standard_switch'),
 ('costing','batch_true_absorption_variance'),('costing','production_overhead_workload_policy'),('costing','production_overhead_scope_factor'),
 ('costing','production_overhead_behaviour_factor'),('costing','production_overhead_resource_factor'),('costing','direct_labour_workload_policy'),
 ('costing','sales_allocation_default_policy'),('costing','default_volume_cap_log'),('costing','production_route_family'),
 ('costing','product_qc_workload_snapshot'),('costing','product_qc_allocation_snapshot'),('costing','sku_qc_allocation_snapshot'),('public','production_batch_size_ref')),
c as (select t.s,t.n, string_agg(format('%I %s%s%s', a.attname, format_type(a.atttypid,a.atttypmod),
        case when pg_get_expr(d.adbin,d.adrelid) like 'nextval%' then ' generated by default as identity' when d.adbin is not null then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,
        case when a.attnotnull then ' not null' else '' end), ', ' order by a.attnum) cols
      from t join pg_class r on r.relname=t.n join pg_namespace ns on ns.oid=r.relnamespace and ns.nspname=t.s
      join pg_attribute a on a.attrelid=r.oid and a.attnum>0 and not a.attisdropped
      left join pg_attrdef d on d.adrelid=r.oid and d.adnum=a.attnum
      group by t.s,t.n),
k as (select ns.nspname s, r.relname n, string_agg(format('alter table %I.%I add constraint %I %s;', ns.nspname, r.relname, co.conname, pg_get_constraintdef(co.oid)), E'\n') cons
      from pg_constraint co join pg_class r on r.oid=co.conrelid join pg_namespace ns on ns.oid=r.relnamespace
      join t on t.s=ns.nspname and t.n=r.relname where co.contype in ('p','u','c') group by 1,2)
select json_agg(json_build_object('s',c.s,'n',c.n,'ddl',format('create table %I.%I (%s);', c.s, c.n, c.cols),'cons',k.cons)) from c left join k using(s,n)
